128→func (c *CursorAgent) parsePreCompact(stdin io.Reader) (*agent.Event, error) {
129→	raw, err := agent.ReadAndParseHookInput[preCompactHookInputRaw](stdin)
130→	if err != nil {
131→		return nil, err
132→	}
133→	return &agent.Event{
134→		Type:       agent.Compaction,
