141→func (c *CursorAgent) parseSubagentStart(stdin io.Reader) (*agent.Event, error) {
142→	raw, err := agent.ReadAndParseHookInput[subagentStartHookInputRaw](stdin)
143→	if err != nil {
144→		return nil, err
145→	}
146→	if raw.Task == "" {
147→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
148→	}
149→	return &agent.Event{
150→		Type:            agent.SubagentStart,
151→		SessionID:       raw.ConversationID,
152→		SessionRef:      raw.TranscriptPath,
153→		SubagentID:      raw.SubagentID,
154→		ToolUseID:       raw.SubagentID,
155→		SubagentType:    raw.SubagentType,
156→		TaskDescription: raw.Task,
157→		Timestamp:       time.Now(),
158→	}, nil
159→}
160→
161→func (c *CursorAgent) parseSubagentStop(stdin io.Reader) (*agent.Event, error) {
162→	raw, err := agent.ReadAndParseHookInput[subagentStopHookInputRaw](stdin)
163→	if err != nil {
164→		return nil, err
165→	}
166→	if raw.Task == "" {
167→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
168→	}
169→	event := &agent.Event{
170→		Type:            agent.SubagentEnd,
171→		SessionID:       raw.ConversationID,
172→		SessionRef:      raw.TranscriptPath,
173→		ToolUseID:       raw.SubagentID,
174→		SubagentType:    raw.SubagentType,
175→		TaskDescription: raw.Task,
176→		Timestamp:       time.Now(),
177→		SubagentID:      raw.SubagentID,
178→	}
179→	return event, nil
180→}
