229→// --- ReadSession ---
230→
231→func TestReadSession_Success(t *testing.T) {
232→	t.Parallel()
233→	tmpDir := t.TempDir()
234→	transcriptPath := writeSampleTranscript(t, tmpDir)
235→
236→	ag := &CursorAgent{}
237→	input := &agent.HookInput{
238→		SessionID:  "cursor-session-1",
239→		SessionRef: transcriptPath,
240→	}
241→
242→	session, err := ag.ReadSession(input)
243→	if err != nil {
244→		t.Fatalf("ReadSession() error = %v", err)
245→	}
