177→// CalculateTokenUsage calculates token usage from a Claude Code transcript.
178→// This is specific to Claude/Anthropic's API format where each assistant message
179→// contains a usage object with input_tokens, output_tokens, and cache tokens.
180→//
181→// Due to streaming, multiple transcript rows may share the same message.id.
182→// We deduplicate by taking the row with the highest output_tokens for each message.id.
183→func CalculateTokenUsage(transcript []TranscriptLine) *agent.TokenUsage {
184→	// Map from message.id to the usage with highest output_tokens
185→	usageByMessageID := make(map[string]messageUsage)
186→
187→	for _, line := range transcript {
188→		if line.Type != "assistant" {
189→			continue
190→		}
191→
192→		var msg messageWithUsage
193→		if err := json.Unmarshal(line.Message, &msg); err != nil {
194→			continue
195→		}
196→
197→		if msg.ID == "" {
198→			continue
199→		}
200→
201→		// Keep the entry with highest output_tokens (final streaming state)
202→		existing, exists := usageByMessageID[msg.ID]
203→		if !exists || msg.Usage.OutputTokens > existing.OutputTokens {
204→			usageByMessageID[msg.ID] = msg.Usage
205→		}
206→	}
207→
208→	// Sum up all unique messages
209→	usage := &agent.TokenUsage{
210→		APICallCount: len(usageByMessageID),
211→	}
212→	for _, u := range usageByMessageID {
213→		usage.InputTokens += u.InputTokens
214→		usage.CacheCreationTokens += u.CacheCreationInputTokens
215→		usage.CacheReadTokens += u.CacheReadInputTokens
216→		usage.OutputTokens += u.OutputTokens
217→	}
218→
219→	return usage
220→}
221→
222→// CalculateTokenUsageFromFile calculates token usage from a Claude Code transcript file.
223→// If startLine > 0, only considers lines from startLine onwards.
224→func CalculateTokenUsageFromFile(path string, startLine int) (*agent.TokenUsage, error) {
225→	if path == "" {
226→		return &agent.TokenUsage{}, nil
227→	}
228→
229→	lines, err := transcript.ParseFromFileAtLine(path, startLine)
230→	if err != nil {
231→		return nil, err //nolint:wrapcheck // caller adds context
232→	}
233→
234→	return CalculateTokenUsage(lines), nil
235→}
236→
237→// ExtractSpawnedAgentIDs extracts agent IDs from Task tool results in a transcript.
238→// When a Task tool completes, the tool_result contains "agentId: <id>" in its content.
239→// Returns a map of agentID -> toolUseID for all spawned agents.
240→func ExtractSpawnedAgentIDs(transcript []TranscriptLine) map[string]string {
241→	agentIDs := make(map[string]string)
242→
243→	for _, line := range transcript {
244→		if line.Type != "user" {
245→			continue
246→		}
247→
248→		// Parse as array of content blocks (tool results)
249→		var contentBlocks []struct {
250→			Type      string          `json:"type"`
251→			ToolUseID string          `json:"tool_use_id"`
252→			Content   json.RawMessage `json:"content"`
253→		}
254→
255→		var msg struct {
256→			Content json.RawMessage `json:"content"`
257→		}
258→		if err := json.Unmarshal(line.Message, &msg); err != nil {
259→			continue
260→		}
261→
262→		if err := json.Unmarshal(msg.Content, &contentBlocks); err != nil {
263→			continue
264→		}
265→
266→		for _, block := range contentBlocks {
267→			if block.Type != "tool_result" {
268→				continue
269→			}
270→
271→			// Content can be a string or array of text blocks
272→			var textContent string
273→
274→			// Try as array of text blocks first
275→			var textBlocks []struct {
276→				Type string `json:"type"`
277→				Text string `json:"text"`
278→			}
279→			if err := json.Unmarshal(block.Content, &textBlocks); err == nil {
280→				var textContentSb361 strings.Builder
281→				for _, tb := range textBlocks {
282→					if tb.Type == "text" {
283→						textContentSb361.WriteString(tb.Text + "\n")
284→					}
285→				}
286→				textContent += textContentSb361.String()
287→			} else {
288→				// Try as plain string
289→				var str string
290→				if err := json.Unmarshal(block.Content, &str); err == nil {
291→					textContent = str
292→				}
293→			}
294→
295→			// Look for agentId in the text
296→			if agentID := extractAgentIDFromText(textContent); agentID != "" {
297→				agentIDs[agentID] = block.ToolUseID
298→			}
299→		}
300→	}
301→
302→	return agentIDs
303→}
304→
305→// extractAgentIDFromText extracts an agent ID from text containing "agentId: <id>".
306→func extractAgentIDFromText(text string) string {
307→	const prefix = "agentId: "
308→	idx := strings.Index(text, prefix)
309→	if idx == -1 {
310→		return ""
311→	}
312→
313→	// Extract the ID (alphanumeric characters after the prefix)
314→	start := idx + len(prefix)
315→	end := start
316→	for end < len(text) && (text[end] >= 'a' && text[end] <= 'z' ||
317→		text[end] >= 'A' && text[end] <= 'Z' ||
318→		text[end] >= '0' && text[end] <= '9') {
319→		end++
320→	}
321→
322→	if end > start {
323→		return text[start:end]
324→	}
325→	return ""
326→}
327→
328→// CalculateTotalTokenUsage calculates token usage for a turn, including subagents.
329→// It parses the main transcript bytes from startLine, extracts spawned agent IDs,
330→// and calculates their token usage from transcript files in subagentsDir.
331→func (c *ClaudeCodeAgent) CalculateTotalTokenUsage(transcriptData []byte, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
332→	if len(transcriptData) == 0 {
333→		return &agent.TokenUsage{}, nil
334→	}
335→
336→	// Slice to the relevant portion and parse
337→	sliced := transcript.SliceFromLine(transcriptData, startLine)
338→	parsed, err := transcript.ParseFromBytes(sliced)
339→	if err != nil {
340→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
341→	}
342→
343→	// Calculate token usage from parsed transcript
344→	mainUsage := CalculateTokenUsage(parsed)
345→
346→	// Extract spawned agent IDs from the same parsed transcript
347→	agentIDs := ExtractSpawnedAgentIDs(parsed)
348→
349→	// Calculate subagent token usage (skip when subagentsDir is empty to avoid reading from cwd)
350→	if len(agentIDs) > 0 && subagentsDir != "" {
351→		subagentUsage := &agent.TokenUsage{}
352→		for agentID := range agentIDs {
353→			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
354→			agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
355→			if err != nil {
356→				// Agent transcript may not exist yet or may have been cleaned up
357→				continue
358→			}
359→			subagentUsage.InputTokens += agentUsage.InputTokens
360→			subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
361→			subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
362→			subagentUsage.OutputTokens += agentUsage.OutputTokens
363→			subagentUsage.APICallCount += agentUsage.APICallCount
364→		}
365→		if subagentUsage.APICallCount > 0 {
366→			mainUsage.SubagentTokens = subagentUsage
367→		}
368→	}
369→
370→	return mainUsage, nil
371→}
372→
373→// ExtractAllModifiedFiles extracts files modified by both the main agent and
374→// any subagents spawned via the Task tool. It parses the main transcript bytes from
375→// startLine, collects modified files from the main agent, then reads each
376→// subagent's transcript from subagentsDir to collect their modified files too.
377→// The result is a deduplicated list of all modified file paths.
378→func (c *ClaudeCodeAgent) ExtractAllModifiedFiles(transcriptData []byte, startLine int, subagentsDir string) ([]string, error) {
379→	if len(transcriptData) == 0 {
380→		return nil, nil
381→	}
382→
383→	// Slice to the relevant portion and parse
384→	sliced := transcript.SliceFromLine(transcriptData, startLine)
385→	parsed, err := transcript.ParseFromBytes(sliced)
386→	if err != nil {
387→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
388→	}
389→
390→	// Collect modified files from main agent
391→	fileSet := make(map[string]bool)
392→	var files []string
393→	for _, f := range ExtractModifiedFiles(parsed) {
394→		if !fileSet[f] {
395→			fileSet[f] = true
396→			files = append(files, f)
397→		}
398→	}
399→
400→	// Find spawned subagents and collect their modified files (skip when subagentsDir is empty to avoid reading from cwd)
401→	agentIDs := ExtractSpawnedAgentIDs(parsed)
402→	if subagentsDir == "" {
403→		return files, nil
404→	}
405→	for agentID := range agentIDs {
406→		agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
407→		agentLines, agentErr := transcript.ParseFromFileAtLine(agentPath, 0)
408→		if agentErr != nil {
409→			// Subagent transcript may not exist yet or may have been cleaned up
410→			continue
411→		}
412→		for _, f := range ExtractModifiedFiles(agentLines) {
413→			if !fileSet[f] {
414→				fileSet[f] = true
415→				files = append(files, f)
416→			}
417→		}
418→	}
419→
420→	return files, nil
421→}
