 53→// DetectPresence checks if Claude Code is configured in the repository.
 54→func (c *ClaudeCodeAgent) DetectPresence(ctx context.Context) (bool, error) {
 55→	// Get worktree root to check for .claude directory
 56→	// This is needed because the CLI may be run from a subdirectory
 57→	repoRoot, err := paths.WorktreeRoot(ctx)
 58→	if err != nil {
 59→		// Not in a git repo, fall back to CWD-relative check
 60→		repoRoot = "."
 61→	}
 62→
 63→	// Check for .claude directory
 64→	claudeDir := filepath.Join(repoRoot, ".claude")
 65→	if _, err := os.Stat(claudeDir); err == nil {
 66→		return true, nil
 67→	}
 68→	// Check for .claude/settings.json
 69→	settingsFile := filepath.Join(repoRoot, ".claude", "settings.json")
 70→	if _, err := os.Stat(settingsFile); err == nil {
 71→		return true, nil
 72→	}
 73→	return false, nil
 74→}
