106→// ReadSession reads a session from Claude's storage (JSONL transcript file).
107→// The session data is stored in NativeData as raw JSONL bytes.
108→// ModifiedFiles is computed by parsing the transcript.
109→func (c *ClaudeCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
110→	if input.SessionRef == "" {
111→		return nil, errors.New("session reference (transcript path) is required")
112→	}
113→
114→	// Read the raw JSONL file
115→	data, err := os.ReadFile(input.SessionRef)
116→	if err != nil {
117→		return nil, fmt.Errorf("failed to read transcript: %w", err)
118→	}
119→
120→	// Parse to extract computed fields
121→	lines, err := transcript.ParseFromBytes(data)
122→	if err != nil {
123→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
124→	}
125→
126→	return &agent.AgentSession{
127→		SessionID:     input.SessionID,
128→		AgentName:     c.Name(),
129→		SessionRef:    input.SessionRef,
130→		StartTime:     time.Now(),
131→		NativeData:    data,
132→		ModifiedFiles: ExtractModifiedFiles(lines),
133→	}, nil
134→}
135→
136→// WriteSession writes a session to Claude's storage (JSONL transcript file).
137→// Uses the NativeData field which contains raw JSONL bytes.
138→// The session must have been created by Claude Code (AgentName check).
139→func (c *ClaudeCodeAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
140→	if session == nil {
141→		return errors.New("session is nil")
142→	}
143→
144→	// Verify this session belongs to Claude Code
145→	if session.AgentName != "" && session.AgentName != c.Name() {
146→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
147→	}
148→
149→	if session.SessionRef == "" {
150→		return errors.New("session reference (transcript path) is required")
151→	}
152→
153→	if len(session.NativeData) == 0 {
154→		return errors.New("session has no native data to write")
155→	}
156→
157→	// Write the raw JSONL data
158→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
159→		return fmt.Errorf("failed to write transcript: %w", err)
160→	}
161→
162→	return nil
163→}
