187→// TruncateAtUUID returns a new session truncated at the given UUID (inclusive).
188→// This is used for rewind operations to restore transcript state.
189→// Requires NativeData to be populated.
190→func (c *ClaudeCodeAgent) TruncateAtUUID(session *agent.AgentSession, uuid string) (*agent.AgentSession, error) {
191→	if session == nil {
192→		return nil, errors.New("session is nil")
193→	}
194→
195→	if len(session.NativeData) == 0 {
196→		return nil, errors.New("session has no native data")
197→	}
198→
199→	if uuid == "" {
200→		// No truncation needed, return copy
201→		return &agent.AgentSession{
202→			SessionID:     session.SessionID,
203→			AgentName:     session.AgentName,
204→			RepoPath:      session.RepoPath,
205→			SessionRef:    session.SessionRef,
206→			StartTime:     session.StartTime,
207→			NativeData:    session.NativeData,
208→			ModifiedFiles: session.ModifiedFiles,
209→		}, nil
210→	}
211→
212→	// Parse, truncate, re-serialize
213→	lines, err := transcript.ParseFromBytes(session.NativeData)
214→	if err != nil {
215→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
216→	}
217→
218→	truncated := TruncateAtUUID(lines, uuid)
219→
220→	newData, err := SerializeTranscript(truncated)
221→	if err != nil {
222→		return nil, fmt.Errorf("failed to serialize truncated transcript: %w", err)
223→	}
224→
225→	return &agent.AgentSession{
226→		SessionID:     session.SessionID,
227→		AgentName:     session.AgentName,
228→		RepoPath:      session.RepoPath,
229→		SessionRef:    session.SessionRef,
230→		StartTime:     session.StartTime,
231→		NativeData:    newData,
232→		ModifiedFiles: ExtractModifiedFiles(truncated),
233→	}, nil
234→}
