236→// FindCheckpointUUID finds the UUID of the message containing the tool_result
237→// for the given tool use ID. Used for task checkpoint rewind.
238→// Returns the UUID and true if found, empty string and false otherwise.
239→func (c *ClaudeCodeAgent) FindCheckpointUUID(session *agent.AgentSession, toolUseID string) (string, bool) {
240→	if session == nil || len(session.NativeData) == 0 {
241→		return "", false
242→	}
243→
244→	lines, err := transcript.ParseFromBytes(session.NativeData)
245→	if err != nil {
246→		return "", false
247→	}
