261→// SanitizePathForClaude converts a path to Claude's project directory format.
262→// Claude replaces any non-alphanumeric character with a dash.
263→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
264→
265→func SanitizePathForClaude(path string) string {
266→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
