357→// ChunkTranscript splits a JSONL transcript at line boundaries.
358→// Claude Code uses JSONL format (one JSON object per line), so chunking
359→// is done at newline boundaries to preserve message integrity.
360→func (c *ClaudeCodeAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
361→	chunks, err := agent.ChunkJSONL(content, maxSize)
362→	if err != nil {
363→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
364→	}
365→	return chunks, nil
366→}
