368→// ReassembleTranscript concatenates JSONL chunks with newlines.
369→//
370→
371→func (c *ClaudeCodeAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
372→	return agent.ReassembleJSONL(chunks), nil
373→}
